<script setup>import{onMounted,ref}from'vue';import{api}from'../api/crm';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),dashboard=ref({customers:0,activeOpportunities:0,pipelineAmount:0,followUpsDue:0,pendingTasks:0}),recent=ref([]);const money=n=>Number(n||0).toLocaleString('zh-CN');onMounted(async()=>{[dashboard.value,recent.value]=await Promise.all([api.dashboard(),api.recentFollowUps()])});const apps=[['新增客户','add-o','/customers?create=1'],['记录跟进','chat-o','/follow-ups'],['销售任务','todo-list-o','/tasks'],['全部功能','apps-o','/workbench']];const methods={PHONE:'电话',WECHAT:'微信',VISIT:'拜访',EMAIL:'邮件',OTHER:'其他'}</script>
<template><div class="page safe-top"><section class="hero brand-gradient"><div><div class="eyebrow">ZHUATECH CRM</div><div class="hello">你好，{{auth.user?.fullName}}</div><div class="muted-light">{{auth.user?.position}} · 今日继续推进客户关系</div></div><van-icon name="chart-trending-o" size="28"/></section><section class="card stats"><div class="stat-row"><div><div class="stat-value">{{dashboard.customers}}</div><div class="stat-label">客户总数</div></div><div><div class="stat-value">{{dashboard.activeOpportunities}}</div><div class="stat-label">进行中商机</div></div><div><div class="stat-value">{{dashboard.followUpsDue}}</div><div class="stat-label">待跟进</div></div></div><div class="pipeline"><span>预计销售漏斗</span><b>¥ {{money(dashboard.pipelineAmount)}}</b></div></section><h2 class="section-title">快捷操作</h2><section class="grid"><router-link v-for="app in apps" :key="app[0]" :to="app[2]" class="app-icon"><span class="circle"><van-icon :name="app[1]"/></span><span>{{app[0]}}</span></router-link></section><h2 class="section-title">最近跟进 <router-link to="/follow-ups">查看全部</router-link></h2><section v-for="item in recent.slice(0,4)" :key="item.id" class="card follow"><div class="follow-head"><b>{{item.customerName}}</b><span class="tag">{{methods[item.method]}}</span></div><p>{{item.content}}</p><div class="muted">{{item.creatorName}} · {{item.followUpAt?.replace('T',' ').slice(0,16)}}</div></section><div v-if="!recent.length" class="empty">还没有跟进记录</div></div></template>
<style scoped>.hero{min-height:145px;border-radius:24px;padding:24px 22px;display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{font-size:10px;letter-spacing:2px;opacity:.7;margin-bottom:14px}.hello{font-size:23px;font-weight:750;margin-bottom:8px}.muted-light{opacity:.78;font-size:13px}.stats{margin:-31px 12px 0;position:relative}.pipeline{margin-top:17px;padding-top:14px;border-top:1px solid #edf0f5;display:flex;justify-content:space-between;color:#66748a;font-size:13px}.pipeline b{color:#2856a8;font-size:16px}.section-title{display:flex;justify-content:space-between}.section-title a{font-size:12px;color:#71829c;text-decoration:none;font-weight:400}.app-icon{text-decoration:none}.follow-head{display:flex;justify-content:space-between}.follow p{margin:9px 0;color:#46566e;font-size:14px;line-height:1.55}</style>
